<?php
$pdo=database();
$employees=$pdo->query('SELECT * FROM employees ORDER BY active DESC,name')->fetchAll();
$payments=$pdo->query('SELECT p.*,e.name FROM employee_payments p JOIN employees e ON e.id=p.employee_id ORDER BY p.paid_date DESC,p.id DESC LIMIT 30')->fetchAll();
$expenses=$pdo->query('SELECT * FROM operating_expenses ORDER BY expense_date DESC,id DESC LIMIT 40')->fetchAll();
$parts=$pdo->query('SELECT * FROM parts_catalog ORDER BY (stock_qty<=min_stock) DESC,name')->fetchAll();
$lowStockList=$pdo->query('SELECT * FROM parts_catalog WHERE stock_qty<=min_stock ORDER BY stock_qty,name')->fetchAll();
$partPurchases=$pdo->query('SELECT pp.*,pc.name AS part_name FROM part_purchases pp JOIN parts_catalog pc ON pc.id=pp.part_id ORDER BY pp.purchase_date DESC,pp.id DESC LIMIT 50')->fetchAll();
$commonParts=[['Filtër vaji','Filtra'],['Filtër ajri','Filtra'],['Filtër kabine','Filtra'],['Filtër karburanti','Filtra'],['Vaj motori 5W-30','Vajra dhe lëngje'],['Vaj motori 5W-40','Vajra dhe lëngje'],['Lëng ftohës','Vajra dhe lëngje'],['Lëng frenash','Vajra dhe lëngje'],['Pllaka frenash të përparme','Frena'],['Pllaka frenash të pasme','Frena'],['Disk frenash','Frena'],['Qirinj ndezjeje','Motori'],['Rrip i motorit','Motori'],['Fshirëse xhami','Karroceria dhe dukshmëria'],['Llambë H7','Elektrike'],['Bateri 12V','Elektrike'],['Kushinetë rrote','Suspensioni dhe drejtimi'],['Krah suspensioni','Suspensioni dhe drejtimi'],['Amortizator','Suspensioni dhe drejtimi'],['Gomë','Goma dhe rrota']];
$month=date('Y-m');$monthExpenseQuery=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM operating_expenses WHERE DATE_FORMAT(expense_date,"%Y-%m")=?');$monthExpenseQuery->execute([$month]);$opsMonth=(float)$monthExpenseQuery->fetchColumn();
$payrollMonthQuery=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM employee_payments WHERE payment_month=?');$payrollMonthQuery->execute([$month]);$payrollMonth=(float)$payrollMonthQuery->fetchColumn();
?>
