<?php if($lowStockList):?><section class="inventory-low-stock-panel"><div class="inventory-alert-symbol">!</div><div class="inventory-low-stock-copy"><b>Duhet rimbushur stoku</b><p><?=count($lowStockList)?> pjesë janë në ose nën pragun minimal.</p></div><div class="inventory-low-stock-tags"><?php foreach(array_slice($lowStockList,0,5) as $lowPart):?><span><?=h($lowPart['name'])?> <b><?=$lowPart['stock_qty']?>/<?=$lowPart['min_stock']?></b></span><?php endforeach;?></div></section><?php endif;?>
