<section class="panel table-panel"><div class="panel-head"><div><h2>Ekipi i servisit</h2><p>Pozitat dhe pagat mujore</p></div></div><div class="table-wrap"><table><thead><tr><th>Punëtori</th><th>Pozita</th><th>Telefoni</th><th>Paga mujore</th><th>Statusi</th><th></th></tr></thead><tbody><?php foreach($employees as $e):?><tr><td><?=h($e['name'])?></td><td><?=h($e['job_title'])?></td><td><?=h($e['phone']?:'—')?></td><td>€<?=number_format((float)$e['monthly_salary'],2)?></td><td><?=$e['active']?'Aktiv':'Joaktiv'?></td><td><form method="post"><?php form_token();?><input type="hidden" name="action" value="employee_toggle"><input type="hidden" name="id" value="<?=$e['id']?>"><button class="btn small-btn"><?=$e['active']?'Çaktivizo':'Aktivizo'?></button></form></td></tr><?php endforeach;?><?php if(!$employees):?><tr><td colspan="6">Ende nuk ka punëtorë të regjistruar.</td></tr><?php endif;?></tbody></table></div></section>
