<section class="panel form-panel"><div class="panel-head"><div><h2>Shto pjesë në katalog</h2><p>Zgjedh një pjesë të zakonshme ose kërko me emër. Emri dhe kategoria plotësohen vetë.</p></div></div><form method="post" class="form-grid"><?php form_token();?><input type="hidden" name="action" value="part_save"><label class="span-2">Zgjedh produktin<select id="commonPartPicker" name="common_part"><option value="custom">＋ Pjesë tjetër — shkruaje vetë</option><?php foreach($commonParts as [$partName,$partCategory]):?><option value="<?=h($partName)?>" data-category="<?=h($partCategory)?>"><?=h($partName)?> · <?=h($partCategory)?></option><?php endforeach;?></select></label><label>Emri i pjesës *<input id="partNameInput" name="name" required placeholder="Shkruaj ose zgjedh pjesën"></label><label>Kategoria *<input id="partCategoryInput" name="category" required placeholder="Filtra, frena, motor..."></label><label>Kodi / SKU<input name="sku"></label><label>Furnitori<input name="supplier" placeholder="Emri i dyqanit ose distributorit"></label><label>Çmimi për copë (€)<input id="newPartUnitCost" type="number" name="unit_cost" min="0" step="0.01" value="0"></label><label>Sasia në stok (copë)<select id="newPartQuantity" name="stock_qty"><?php for($qty=0;$qty<=50;$qty++):?><option value="<?=$qty?>" <?=$qty===1?'selected':''?>><?=$qty?> copë</option><?php endfor;?></select></label><label>Pragu i stokut të ulët<select name="min_stock"><?php for($qty=0;$qty<=20;$qty++):?><option value="<?=$qty?>" <?=$qty===2?'selected':''?>><?=$qty?> copë</option><?php endfor;?></select></label><label class="span-2">Totali i blerjes <strong id="newPartTotal">€0.00</strong><small>Llogaritje automatike: sasia × çmimi për copë</small></label><label>Data e blerjes<input type="date" name="purchase_date" value="<?=date('Y-m-d')?>"></label><div class="span-2"><button class="btn primary">＋ Shto në katalog</button></div></form><script>document.addEventListener('DOMContentLoaded',function(){(function(){const quantity=document.getElementById('newPartQuantity'),unitCost=document.getElementById('newPartUnitCost'),total=document.getElementById('newPartTotal');function updateTotal(){total.textContent='€'+((Number(quantity.value)||0)*(Number(unitCost.value)||0)).toFixed(2);}quantity.addEventListener('change',updateTotal);unitCost.addEventListener('input',updateTotal);updateTotal();const picker=document.getElementById('commonPartPicker'),name=document.getElementById('partNameInput'),category=document.getElementById('partCategoryInput');picker.addEventListener('change',function(){const option=picker.selectedOptions[0];if(picker.value==='custom'){name.value='';category.value='';name.focus();return;}name.value=picker.value;category.value=option.dataset.category||'';});document.querySelectorAll('.part-restock-form').forEach(function(form){const qty=form.elements.quantity,cost=form.elements.unit_cost,label=form.querySelector('.purchase-total-preview');function calc(){label.innerHTML='Totali i blerjes <span>€'+((Number(qty.value)||0)*(Number(cost.value)||0)).toFixed(2)+'</span>';}qty.addEventListener('change',calc);cost.addEventListener('input',calc);calc();});})();});</script></section></div>
<section class="panel table-panel"><div class="panel-head"><div><h2>Katalogu i pjesëve dhe furnitorëve</h2><p>Regjistro blerjen e pjesëve për të përditësuar stokun dhe shpenzimet.</p></div></div><div class="table-wrap"><table><thead><tr><th>Pjesa</th><th>Kategoria / kodi</th><th>Furnitori</th><th>Çmimi i fundit</th><th>Stoku</th><th>Blerje e re</th></tr></thead><tbody><?php foreach($parts as $p):?><tr><td><?=h($p['name'])?></td><td><?=h($p['category'])?><small class="table-sub"><?=h($p['sku']?:'Pa kod')?></small></td><td><?=h($p['supplier']?:'—')?></td><td>€<?=number_format((float)$p['unit_cost'],2)?></td><td><?=$p['stock_qty']?><?php if((int)$p['stock_qty']<=(int)$p['min_stock']):?> <span class="status-pill pending">Stok i ulët</span><?php endif;?></td><td><form method="post" class="inventory-buy-form part-restock-form"><?php form_token();?><input type="hidden" name="action" value="part_stock_add"><input type="hidden" name="id" value="<?=$p['id']?>"><select aria-label="Sasia në copë" name="quantity" required><?php for($qty=1;$qty<=50;$qty++):?><option value="<?=$qty?>" <?=$qty===1?'selected':''?>><?=$qty?> copë</option><?php endfor;?></select><input aria-label="Çmimi për copë" type="number" name="unit_cost" min="0" step="0.01" value="<?=h((string)$p['unit_cost'])?>"><strong class="purchase-total-preview">Totali i blerjes <span>€0.00</span></strong><input aria-label="Data e blerjes" type="date" name="purchase_date" value="<?=date('Y-m-d')?>"><button class="btn small-btn">Regjistro</button></form><form method="post" onsubmit="return confirm('Ta heqim këtë pjesë nga katalogu?')"><?php form_token();?><input type="hidden" name="action" value="part_delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="part-delete-btn" title="Hiq nga katalogu" aria-label="Hiq nga katalogu">×</button></form></td></tr><?php endforeach;?><?php if(!$parts):?><tr><td colspan="6">Katalogu është bosh. Shto pjesët dhe furnitorët me të cilët punon servisi.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel table-panel"><div class="panel-head"><div><h2>Historiku i blerjeve të pjesëve</h2><p>Sasia, çmimi për copë dhe totali i secilës blerje</p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Pjesa</th><th>Sasia</th><th>Çmimi për copë</th><th>Totali</th></tr></thead><tbody><?php foreach($partPurchases as $purchase):?><tr><td><?=h(date('d.m.Y',strtotime($purchase['purchase_date'])))?></td><td><?=h($purchase['part_name'])?></td><td><?=number_format((int)$purchase['quantity'])?> copë</td><td>€<?=number_format((float)$purchase['unit_cost'],2)?></td><td><b>€<?=number_format((float)$purchase['total_cost'],2)?></b></td></tr><?php endforeach;?><?php if(!$partPurchases):?><tr><td colspan="5">Blerjet e regjistruara do të shfaqen këtu.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel table-panel"><div class="panel-head"><div><h2>Pagesat e fundit të pagave</h2><p>Historiku i pagave të regjistruara</p></div></div><div class="table-wrap"><table><thead><tr><th>Punëtori</th><th>Muaji</th><th>Data e pagesës</th><th>Shuma</th><th>Shënim</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=h($p['name'])?></td><td><?=h($p['payment_month'])?></td><td><?=h(date('d.m.Y',strtotime($p['paid_date'])))?></td><td>€<?=number_format((float)$p['amount'],2)?></td><td><?=h($p['note']?:'—')?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="5">Ende nuk ka pagesa të regjistruara.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel table-panel"><div class="panel-head"><div><h2>Shpenzimet operative</h2><p>Faturat e rrymës, pagat dhe kostot e tjera të regjistruara</p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Kategoria</th><th>Përshkrimi</th><th>Shuma</th></tr></thead><tbody><?php foreach($expenses as $e):?><tr><td><?=h(date('d.m.Y',strtotime($e['expense_date'])))?></td><td><?=h($e['category'])?></td><td><?=h($e['description'])?></td><td>€<?=number_format((float)$e['amount'],2)?></td></tr><?php endforeach;?><?php if(!$expenses):?><tr><td colspan="4">Ende nuk ka shpenzime operative të regjistruara.</td></tr><?php endif;?></tbody></table></div></section>
